 return `<h3>书籍归组与手动排序</h3><div class="book-group-list">${books.map((b,index)=>`<div class="book-group-row"><strong>${E(b.title)}</strong><select data-assign-group="${E(b.id)}" aria-label="${E(b.title)}的分组"><option value="">未分组</option>${s.groups.map(g=>`<option value="${E(g.id)}" ${s.assignments[b.id]===g.id?'selected':''}>${E(g.name)}</option>`).join('')}</select><button class="btn secondary small" data-book-move="${E(b.id)}" data-direction="-1" aria-label="${E(b.title)}上移" ${index===0?'disabled':''}>↑</button><button class="btn secondary small" data-book-move="${E(b.id)}" data-direction="1" aria-label="${E(b.title)}下移" ${index===books.length-1?'disabled':''}>↓</button></div>`).join('')}</div>`;
