function groupDialog(){const s=window.BookShelf.clean(state.shelf);openDialog(`<div class="modal-head"><strong>管理书架分组</strong><button class="icon-button" data-close-dialog aria-label="关闭分组管理">${icon('close')}</button></div><div class="modal-body group-manager"><p>每本书可归入一个分组；移除分组后，书籍回到“未分组”。</p><label class="group-add">新分组<input id="new-group-name" maxlength="40" placeholder="例如：校园故事"><button class="btn" data-add-group>创建分组</button></label><div class="group-list">${s.groups.map(g=>`<div class="group-edit"><input data-group-name="${E(g.id)}" aria-label="重命名分组 ${E(g.name)}" maxlength="40" value="${E(g.name)}"><span>${storyBooks().filter(b=>s.assignments[b.id]===g.id).length} 本</span><button class="btn secondary small" data-rename-group="${E(g.id)}">保存名称</button><button class="btn ghost small" data-delete-group="${E(g.id)}" title="仅移除分组，保留书籍">移除分组</button></div>`).join('')||'<p>还没有自定义分组。创建后可在书架上分配书籍。</p>'}</div>${groupAssignments(s)}</div>`,'group-modal');}
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-shelf-filter]')){state.shelf.filter=t.value;persist();render();}if(t.matches('[data-shelf-sort]')){state.shelf.sort=t.value;persist();render();}if(t.matches('[data-assign-group]')){state.shelf=window.BookShelf.assign(state.shelf,t.dataset.assignGroup,t.value);const y=$('.workspace')?.scrollTop||0;persist();render();$('.workspace').scrollTop=y;notify('书籍分组已保存。');}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset;try{if('bookOrigin'in a){originFilter=a.bookOrigin;render();}if('resetShelf'in a){originFilter='all';search='';state.shelf.filter='all';persist();render();}if(a.shelfMode){state.shelf.mode=a.shelfMode;persist();render();}if('manageGroups'in a)groupDialog();if(a.bookMove){const ordered=window.BookShelf.sorted(visibleBooks(),{...state.shelf,sort:'manual'}).map(b=>b.id);const index=ordered.indexOf(a.bookMove),next=index+Number(a.direction);if(index>=0&&next>=0&&next<ordered.length){[ordered[index],ordered[next]]=[ordered[next],ordered[index]];state.shelf.order=ordered;state.shelf.sort='manual';persist();render();groupDialog();}}if('addGroup'in a){state.shelf=window.BookShelf.saveGroup(state.shelf,'g-'+(crypto.randomUUID?.()||[...crypto.getRandomValues(new Uint32Array(3))].map(n=>n.toString(36)).join('-')),$('#new-group-name').value);persist();render();groupDialog();}if(a.renameGroup){state.shelf=window.BookShelf.saveGroup(state.shelf,a.renameGroup,$(`[data-group-name="${a.renameGroup}"]`).value);persist();render();groupDialog();}if(a.deleteGroup){state.shelf=window.BookShelf.removeGroup(state.shelf,a.deleteGroup);persist();render();groupDialog();notify('分组已移除，书籍仍在书架中。');}}catch(err){notify(err.message);}});
function bookPage(){const book=activeBook();let html=bookPageContent().replace('<div class="breadcrumb">',`<div class="breadcrumb"><button class="icon-button book-back" data-nav="${isSceneBook(book)?'scenes':'shelf'}" aria-label="返回书架" title="返回书架">${icon('back')}</button>`);html=html.replace(/<h2>章节目录(?:<small>.*?<\/small>)?<\/h2>/,`<h2>章节目录</h2><button class="btn secondary small" data-chapter-layout>${state.settings.chapterList?'卡片模式':'列表模式'}</button>`).replace('class="chapter-grid"',`class="chapter-grid ${state.settings.chapterList?'chapter-list':''}"`);if(book.imported)html=html.replace(/(<button class="btn" data-open-chapter="[^"]+">.*?<\/button>)/,`<div class="book-intro-actions">$1<button class="btn secondary" data-book-actions="${E(book.id)}">管理本书</button></div>`);else html=html.replace('</section>',`<div class="book-manage-inline"><button class="btn secondary" data-book-actions="${E(book.id)}">管理本书</button></div></section>`);if(isSceneBook(book))html=html.replace('data-nav="shelf">故事书架','data-nav="scenes">专题场景');return html;}
 document.addEventListener('click',e=>{if(e.target.closest('[data-chapter-layout]')){state.settings.chapterList=!state.settings.chapterList;persist();render();}});

function bookPageContent(){if(window.DkDictionary.isBook(activeBook()))return dk.bookPage(activeBook());if(window.TravelCourse.isBook(activeBook()))return travel.bookPage(activeBook(),shelfFilter);if(activeBook().imported)return importedBookPage();const today=C.ensureDay(state);const last=lastInBook(activeBook());const started=state.progress[last.id];const q='';let chapters=bookChapters().filter(c=>!q||[c.title,c.scene,c.blurb,...c.tags].join(' ').toLowerCase().includes(q));if(shelfFilter==='unread')chapters=chapters.filter(c=>!state.progress[c.id]?.completed);if(shelfFilter==='read')chapters=chapters.filter(c=>state.progress[c.id]?.completed);const matches=q?Object.values(D.words).filter(w=>w.key.includes(q)||w.glosses.some(g=>g.includes(q))).slice(0,12):[];
return `<div class="page"><div class="page-heading"><div><div class="breadcrumb"><button data-nav="shelf">故事书架</button><span>/</span><span>书籍详情</span></div><h1>${E(activeBook().title)}<small class="book-volume">${E(activeBook().volume)}</small></h1><p>${E(activeBook().learningSummary)}</p></div><span class="pill">第一辑 · 12 个完整故事</span></div>${studio.bookSummary(activeBook().id)}${!q?`<section class="hero" aria-label="开始阅读"><div class="hero-copy"><div class="eyebrow">校园异闻 / VOL. 01</div><h2>从报到第一晚，<br>开始你的故事。</h2><p>天生灵力强的大一新生，遇上超自然研究社。<br>今晚的宿舍，似乎有位室友还没自我介绍。</p><div class="hero-actions"><button class="btn" data-open-chapter="${last.id}">${icon('book')}${started?'继续阅读 · '+last.scene:'开始第一章'}${icon('arrow')}</button><small>不急，慢慢读就好。</small></div></div><div class="hero-illustration">${heroArt()}<span class="hero-caption">一个场景 · 一场小冒险</span></div></section><div class="stat-strip"><div class="stat"><div class="stat-top">${icon('book')}故事进度</div><strong>${completedCount()}<small>/ 12 章</small></strong></div><div class="stat"><div class="stat-top">${icon('bookmark')}收藏的词语</div><strong>${Object.keys(state.saved).length}<small>个</small></strong></div><div class="stat"><div class="stat-top">${icon('clock')}阅读时光</div><strong>${Math.floor(totalSeconds()/60)}<small>分钟</small></strong></div><div class="stat"><div class="stat-top">${icon('leaf')}今日练习</div><strong>${today.answered+today.reviewed}<small>/ ${state.settings.goal} 次</small></strong></div></div>`:''}${q&&matches.length?`<div class="section-heading"><h2>找到的词语 <small>最多显示 12 项</small></h2></div><div class="search-result-list">${matches.map(w=>`<button class="search-result" data-open-word="${w.id}"><strong>${E(w.en)}</strong><span>${E(w.glosses[0])}</span><small>${E(chapter(w.chapters[0]).scene)} ${icon('chevron')}</small></button>`).join('')}</div>`:''}<div class="section-heading"><h2>${q?'章节搜索结果':'章节目录'}<small>${chapters.length} 个故事</small></h2><div class="filter-row" aria-label="章节筛选">${[['all','全部章节'],['unread','还没读完'],['read','已经读完']].map(([id,t])=>`<button class="filter ${shelfFilter===id?'active':''}" data-shelf-filter="${id}" aria-pressed="${shelfFilter===id}">${t}</button>`).join('')}</div></div><div class="chapter-grid">${chapters.map(c=>{const pr=state.progress[c.id];return `<button class="chapter-card" data-open-chapter="${c.id}" aria-label="第${c.number}章 ${E(c.scene)}，${E(c.title)}"><div class="card-art" style="--card-bg:${palette[(c.number-1)%palette.length][0]};--card-ink:${palette[(c.number-1)%palette.length][1]}"><span class="card-number">CHAPTER ${String(c.number).padStart(2,'0')}</span>${pr?.completed?'<span class="card-status">已读完 ✓</span>':pr?.ratio>0?`<span class="card-status">读到 ${Math.round(pr.ratio*100)}%</span>`:''}${sceneArt(c.icon)}</div><div class="card-body"><div class="card-scene">${E(c.scene)} · ${E(c.tags[0])}</div><h3>${E(c.title)}</h3><p>${E(c.blurb)}</p><div class="card-bottom"><span>${c.wordIds.length} 个词语</span><span>约 ${c.minutes} 分钟</span>${icon('arrow')}</div></div></button>`;}).join('')}</div>${!chapters.length?`<div class="empty">${icon('search')}<h3>${q?'暂时没有找到这个故事':'这里还没有故事'}</h3><p>${q?'换一个场景名或单词试试，也可以清空搜索看全部章节。':'阅读后点击章末的「标记已读完」，就会出现在这里。'}</p><button class="btn secondary" data-clear-search>查看全部故事</button></div>`:''}${!q?`<div class="book-intro"><div class="person"><strong>沈知遥 · 大一新生</strong>天生灵力强，鬼见了也得讲道理。<br>刚进大学，先替室友解决一面闹鬼的镜子。</div><div class="person"><strong>陆时屿 · 大三学长</strong>超自然研究社社长，擅长符阵和调查。<br>她负责破局，他把后续稳稳接住。</div><div class="person"><strong>许桃 · 室友与搭档</strong>敢问、会记，也爱吃零食。<br>总能从日常小事里找出关键线索。</div></div><footer class="book-footer"><span>独立单元故事 · 英语四级词汇 + 常用场景词</span><span>内容审阅稿 / ${D.stats.wordEntries.toLocaleString()} 个去重词语条目</span></footer>`:''}</div>`;}
function importedBookPage(){const b=activeBook(),all=bookChapters(),volume=bookVolumes.get(b.id)||'all',volumes=[...new Map(all.filter(c=>c.volumeTitle).map(c=>[c.volumeKey,c.volumeTitle])).entries()],items=all.filter(c=>volume==='all'||c.volumeKey===volume).filter(c=>shelfFilter==='read'?state.progress[c.id]?.completed:shelfFilter==='unread'?!state.progress[c.id]?.completed:true),last=lastInBook(b),pages=Math.max(1,Math.ceil(items.length/60));importedPage=Math.min(importedPage,pages-1);return `<div class="page"><div class="page-heading"><div><div class="breadcrumb"><button data-nav="shelf">故事书架</button><span>/</span>${window.PreparedLibrary.label(b)}</div><h1>${E(b.title)}</h1>${languageBadge(b)}<p>${E(b.learningSummary)}</p></div><span class="pill">${all.length} 个阅读章节</span></div>${studio.bookSummary(b.id)}<section class="imported-intro ${b.prepared?'prepared-intro':''}">${b.prepared?`<div class="prepared-intro-cover">${bookCover(b)}</div>`:''}<p>${E(b.synopsis)}</p><button class="btn" data-open-chapter="${last.id}">${icon('book')}${state.progress[last.id]?'继续阅读':'开始阅读'}</button></section><div class="section-heading"><h2>章节目录</h2>${volumes.length?`<label class="volume-filter">卷名<select data-book-volume aria-label="按卷筛选章节"><option value="all">全部卷</option>${volumes.map(([id,name])=>`<option value="${E(id)}" ${volume===id?'selected':''}>${E(name)}</option>`).join('')}</select></label>`:''}<div class="filter-row">${[['all','全部章节'],['unread','还没读完'],['read','已经读完']].map(([id,t])=>`<button class="filter ${shelfFilter===id?'active':''}" data-shelf-filter="${id}">${t}</button>`).join('')}</div></div><div class="chapter-grid">${items.slice(importedPage*60,(importedPage+1)*60).map((c,i,page)=>`${c.volumeTitle&&(i===0||page[i-1].volumeKey!==c.volumeKey)?`<h3 class="chapter-volume-title">${E(c.volumeTitle)}</h3>`:''}<button class="chapter-card ${c.volumeTitle?'volume-chapter':''}" data-open-chapter="${c.id}"><div class="card-body"><div class="card-scene">${c.sourceNumber?'第 '+E(c.sourceNumber)+' 章':c.volumeTitle?'介绍':'第 '+c.number+' 节'}${state.progress[c.id]?.completed?' · 已读完':''}</div><h3>${E(c.chapterName||c.title)}</h3><p>${E(c.blurb)}</p><div class="card-bottom"><span>${c.wordIds.length} 个词语</span><span>约 ${c.minutes} 分钟</span>${icon('arrow')}</div></div></button>`).join('')}</div><div class="settings-actions"><button class="btn secondary" data-book-page="-1" ${importedPage===0?'disabled':''}>上一页</button><span>${importedPage+1} / ${pages}</span><button class="btn secondary" data-book-page="1" ${importedPage+1>=pages?'disabled':''}>下一页</button></div></div>`;}
document.addEventListener("change",e=>{if(e.target.matches("[data-book-volume]")){bookVolumes.set(activeBook().id,e.target.value);importedPage=0;render();}});
async function ttsDialog(){await window.Pronunciation.ready.catch(()=>{});const info=LocalTTS.info();openDialog(`<div class="modal-head"><span>本地朗读与扩展</span><button class="icon-button" data-close-dialog aria-label="关闭朗读设置">${icon('close')}</button></div><div class="modal-body tts-manager">${window.Pronunciation.controls(E)}<h3>Windows 本地 TTS 设置</h3><p>例句和词库外新词使用本地 TTS；单词音频包不会改变例句声音。没有 TTS 扩展时，使用浏览器提供的本地英语声音。</p><label>导入扩展连接文件<input id="tts-extension-file" type="file" accept=".json,application/json"></label><p>首次解压扩展并双击“启用网页启动.cmd”，再导入同目录的连接 JSON。以后点下方按钮即可启动，无需再找 EXE。请保留扩展文件夹的位置；浏览器可能询问是否打开应用。</p><div class="settings-actions"><button class="btn secondary" data-start-tts>启动本地 TTS</button><span class="tts-launch-note">${info.connected?'已保存扩展连接':'尚未导入连接文件'}</span></div><label for="tts-test-text">试读英语</label><textarea id="tts-test-text" maxlength="2000">The library is quiet. I put my luggage beside the window.</textarea><div class="settings-actions"><button class="btn" data-test-tts>${icon('sound')}朗读</button><button class="btn secondary" data-stop-tts>停止</button>${info.connected?'<button class="btn ghost" data-remove-tts>切回系统语音</button>':''}</div><p class="tts-status" data-tts-status role="status">点击朗读可检查声音是否可用。</p></div>`,'tts-modal');}
document.addEventListener('change',async e=>{if(e.target.id!=='tts-extension-file')return;const f=e.target.files[0];if(!f)return;try{const info=await LocalTTS.install(f);ttsDialog();notify(info.pending?'连接已保存，请点击“启动本地 TTS”。':'扩展已连接：'+info.voices.join('、'));}catch(err){notify(err.message);const el=document.querySelector('[data-tts-status]');if(el)el.textContent=err.message;}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if('startTts'in b.dataset){b.disabled=true;LocalTTS.startBridge().catch(err=>notify(err.message)).finally(()=>b.disabled=false);}if('testTts'in b.dataset){stopAudio();LocalTTS.speak(document.getElementById('tts-test-text').value).catch(e=>notify(e.message));}if('removeTts'in b.dataset){LocalTTS.remove();ttsDialog();}});
document.addEventListener('change',e=>{const key=e.target.dataset.parallelSetting;if(!['parallelMode','parallelTranslation','parallelGloss','parallelLayout'].includes(key))return;saveScroll();if(key==='parallelMode'){const v=e.target.value;state.settings.parallelTranslation=v==='zh'?'hide-en':v==='en'?'hide':'show';state.settings.parallelLayout=v==='zh'||v==='zh-en'?'zh-en':'en-zh';}else state.settings[key]=e.target.value;persist();render();});
function tokenHTML(token,chapterId,pi){return studio.wordToken(token,chapterId,pi,selected);}
function paragraphTarget(index){const p=document.getElementById('paragraph-'+index);return p&&!p.getClientRects().length?[...p.closest('.parallel-row')?.querySelectorAll('.parallel-chinese,.parallel-english')||[]].find(el=>el.getClientRects().length)||p:p;}
function storyHTML(c){if(c.bilingual)return window.BilingualReader.render(c,{E,settings:state.settings,profile:studio.profile(c.bookId),lexicon:window.LEXICON_DATA,design:window.ReadingDesign});if(c.textbookPages)return studio.figure(c,'inline')+window.FunnyReader.render(c,{E,tokenHTML});const point=c.id==='ch01'?24:Math.min(10,c.paragraphs.length-1);return c.paragraphs.map((tokens,pi)=>`${c.sectionTitles?.[pi]?`<h2 class="story-section-title">${E(c.sectionTitles[pi])}</h2>`:''}<p id="paragraph-${pi}" data-p="${pi}">${tokens.map(t=>tokenHTML(t,c.id,pi)).join('')}</p>${pi===point?studio.figure(c,'inline'):''}`).join('');}
function reader(){const c=currentChapter||chapter(state.lastChapter),p=state.progress[c.id],learnIds=c.bilingual?studio.studyIds(c):c.sceneWordIds,b=activeBook(),txtImport=b.imported&&!b.prepared;if(window.DkDictionary.isChapter(c))return dk.reader(c);if(window.TravelCourse.isChapter(c))return travel.reader(c);return `<div class="reader-page ${b.textbook?'fixed-vocabulary-reader':''} ${c.bilingual?'bilingual-reader-page':''}"><div class="reader-top"><div class="breadcrumb"><button data-nav="${isSceneBook(b)?'scenes':'shelf'}">${isSceneBook(b)?'专题场景':'故事书架'}</button><span>/</span><button data-open-book="${E(c.bookId)}">${E(b.title)}</button><span>/</span><span>第 ${String(c.number).padStart(2,'0')} 章 · ${E(c.scene)}</span></div><div class="reader-top-right">${txtImport?'':readingTools.toolbar()}<button class="btn ghost small" data-start-quiz="${c.id}">${icon('target')}章节练习</button></div></div><div class="reader-grid"><section class="reader-main" aria-label="故事阅读"><div class="reader-toolbar"><button class="icon-button reader-back" data-nav="book" aria-label="返回章节目录">${icon('back')}</button>${c.bilingual?window.BilingualReader.controls(state.settings,c):`<div class="mode-switch" role="group" aria-label="阅读模式">${[['learn','双语学习'],['recall','隐藏中文'],['spell','隐藏英文'],['chinese','纯中文'],['challenge','挑战']].map(([m,label])=>`<button data-mode="${m}" class="${state.settings.mode===m?'active':''}" aria-pressed="${state.settings.mode===m}">${label}</button>`).join('')}</div>`}<button class="icon-button reader-read-page" data-read-page-words="${E(c.id)}" aria-label="朗读本页单词" title="朗读本页单词">${icon('sound')}</button>${studio.readerFilterButton(c)}<div class="reading-preferences">${readingTools.fontControls()}<label class="line-height-control" for="reader-line-height">行距<select id="reader-line-height" aria-label="文章行间距">${lineHeightOptions()}</select></label><div class="font-controls" aria-label="字号"><button data-font="-1" aria-label="减小字号">A−</button><span id="font-size-label">${state.settings.fontSize}</span><button data-font="1" aria-label="增大字号">A＋</button></div>${readingTools.positionButton()}${readingTools.button()}</div></div>${studio.readerFilters(c)}<div class="reading-scroll" id="reading-scroll" tabindex="0" aria-label="可滚动的故事正文"><header class="story-header"><div class="story-kicker">${c.volumeTitle?E(c.volumeTitle)+' · '+(c.sourceNumber?'第'+E(c.sourceNumber)+'章':'书籍介绍'):'CHAPTER '+String(c.number).padStart(2,'0')+' · '+E(c.scene)}</div><h1>${E(c.title)}</h1><div class="story-meta">${languageBadge(b)}<span>${E(b.title)}${b.prepared?' · 预制学习书':b.imported?' · TXT 转换':' · 独立单元'}</span><span>${c.bilingual?learnIds.length:c.wordIds.length} 个词语</span><span>约 ${c.minutes} 分钟</span></div><div class="story-divider"></div></header>${studio.figure(c,'chapter')}<article class="story-text" id="story-text" data-mode="${state.settings.mode}">${storyHTML(c)}</article><div class="story-completion"><div class="eyebrow" style="margin-bottom:13px">读到这里，刚刚好</div><h3>这一章，先读到这里。</h3><p>故事读完了。花两分钟，看看还记得哪些词。</p><div class="completion-actions"><button class="btn" data-start-quiz="${c.id}">${icon('target')}练一练本章词语</button><button class="btn secondary" data-complete="${c.id}">${icon('check')}${p?.completed?'已读完':'标记已读完'}</button>${bookChapters()[bookChapters().findIndex(ch=>ch.id===c.id)+1]?`<button class="btn ghost" data-open-chapter="${bookChapters()[bookChapters().findIndex(ch=>ch.id===c.id)+1].id}">下一章 ${icon('arrow')}</button>`:''}</div></div></div><div class="reader-bottom"><div class="progress-track"><span id="read-percent">${Math.round((p?.ratio||0)*100)}%</span><div class="mini-bar"><span id="read-bar" style="width:${(p?.ratio||0)*100}%"></span></div></div><span>进度自动保存在此浏览器</span><button data-nav="book" class="muted">返回目录</button></div></section><aside class="reader-rail" aria-label="词语学习面板"><section class="rail-card" id="word-panel">${wordPanel()}</section><section class="rail-card"><div class="rail-head">场景里的小词库<small>${E(c.scene)}</small></div><div class="scene-words">${learnIds.slice(0,sceneExpanded?undefined:24).map(id=>`<button class="scene-word" data-open-word="${id}" data-word-chapter="${c.id}">${E(D.words[id].en)}</button>`).join('')}</div>${learnIds.length>24?`<button class="btn ghost small" data-expand-scene style="margin:0 9px 10px">${sceneExpanded?'收起词库':'展开全部 '+learnIds.length+' 个词语'}</button>`:''}</section><section class="rail-card"><div class="rail-head">换一个场景<small>${bookChapters().length} 个章节</small></div><div class="chapter-mini-list">${bookChapters().filter((ch,i)=>!b.imported||Math.abs(i-(c.number-1))<12).map(ch=>`<button data-open-chapter="${ch.id}" class="${ch.id===c.id?'current':''}"><span class="n">${String(ch.number).padStart(2,'0')}</span>${E(ch.scene)}${state.progress[ch.id]?.completed?'<span class="done">已读</span>':''}</button>`).join('')}</div></section><p class="rail-tip">词语释义对应本章语境。完整英语例句与故事混排分开呈现，便于记词和辨别用法。</p></aside></div><button class="mobile-word-scrim" data-close-word aria-label="关闭词语面板"></button></div>`;}
function contextText(occurrence,wordId){const c=chapter(occurrence.chapterId);const cn=window.BilingualMechanical.context(c,occurrence.paragraph);if(cn!==undefined)return E(cn);const tokens=c.paragraphs[occurrence.paragraph]||[];return tokens.map(t=>'text'in t?E(t.text):t.id===wordId?`<em>${E(t.en)}（${E(t.zh)}）</em>`:E(c.bilingual?t.en:t.zh)).join('');}

document.addEventListener('change',async e=>{const t=e.target;if(t.matches('[data-word-rate]')){window.Pronunciation.setPreference('rate',Number(t.value));if(selected)speak(selected.id);return;}if(t.matches('[data-card-voice]')){stopAudio();window.Pronunciation.setPreference('voice',t.value);refreshWordCard();if(selected)speak(selected.id);return;}if(t.dataset.voicePref){stopAudio();window.Pronunciation.setPreference(t.dataset.voicePref,t.value);refreshWordCard();ttsDialog();return;}if(t.matches('[data-audio-pack]')&&t.files.length){const files=[...t.files],status=document.querySelector('[data-pack-status]');t.disabled=true;try{const result=await window.AudioImport.importFiles(files,window.Pronunciation,msg=>status.textContent=msg);await ttsDialog();refreshWordCard();const report=document.querySelector('[data-pack-status]');report.textContent='成功导入 '+result.success.length+' 个包'+(result.errors.length?'；失败 '+result.errors.length+' 个：\n'+result.errors.join('\n'):'。请在音色列表中选择。');}catch(err){status.textContent=err.message;t.disabled=false;t.value='';}}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-remove-audio-pack]');if(!b)return;if(!confirm('移除此音频包？默认读音和学习记录会保留。'))return;stopAudio();try{await window.Pronunciation.remove(b.dataset.removeAudioPack);await ttsDialog();notify('音频包已移除。');}catch(err){notify(err.message);}});

function resolveDictionary(id){const w=D.words[id],occ=w?.occurrences?.find(o=>selected?.id===id&&o.chapterId===selected.chapterId&&o.paragraph===selected.paragraph);return window.LearningDictionary.resolve(w?.en,L.entries[id]||{},window.LEARNING_DATA,occ?.gloss||w?.glosses?.[0]||'');}
function wordPanel(innerOnly=false){
 if(!selected)return `<div class="rail-head compact-rail-head"><span>随读词卡</span><button class="icon-button close-word" data-close-word aria-label="关闭词卡">${icon('close')}</button></div><div class="no-word">${icon('leaf')}<p>点击正文中的英文，查看释义与读音。</p></div>`;
 const w=D.words[selected.id],dict=resolveDictionary(w.id),saved=state.saved[w.id],occ=w.occurrences.find(o=>o.chapterId===selected.chapterId&&o.paragraph===selected.paragraph)||w.occurrences.find(o=>o.chapterId===selected.chapterId)||w.occurrences[0];
 if(view==='reader'&&state.settings.mode==='challenge'&&!challengeCardExpanded)return `<div class="rail-head challenge-card-minimized"><span><small>挑战词卡</small>${E(w.en)}</span><button class="btn secondary small" data-expand-challenge-card aria-expanded="false">展开词卡</button><button class="icon-button close-word" data-close-word aria-label="关闭词卡">${icon('close')}</button></div><p class="challenge-card-hint">中文释义只在正文中短暂显示；需要更多信息时再展开。</p>`;
 const source=occ.source==='chinese-mechanical'?'中文译文独立按所选词库机械匹配；不代表英文原著用词，请结合语境核对。':w.dk?(w.dkPhoto?'DK 图解词典 · 写实试绘':'DK汉英双语图解词典 · 用户提供原书图文'):w.travel?window.TravelCourse.wordSource(w,E):w.highRef?`附件高频表 · 第 ${w.highRef.page} 页`:w.fullRef?`附件全量表 · 第 ${w.fullRef.page} 页`:w.source==='import'?'中文释义机械匹配；原标注保留，词卡可查新词库':'场景补充词语';
 const book=D.books.find(b=>b.id===chapter(occ.chapterId)?.bookId),editableTranslation=book?.imported&&!book.prepared;
 const headerTools=view==='reader'&&state.settings.mode==='challenge'?`<button class="icon-button challenge-card-lock ${challengeCardLocked?'active':''}" data-toggle-challenge-lock aria-label="${challengeCardLocked?'取消锁定展开':'锁定词卡展开'}" aria-pressed="${challengeCardLocked}" title="${challengeCardLocked?'已锁定：点击单词时保持展开':'锁定展开'}">${icon('lock')}</button>`:'';
 const translationTools=editableTranslation?`<button class="btn ghost small translation-correction" data-edit-translation>翻译有误</button>`:'';
 return window.WordCard.render({w,dict,occ,saved,E,icon,meaningLabel:occ.source==='chinese-mechanical'?'中文匹配':chapter(occ.chapterId)?.bilingual?"词库义":chapter(occ.chapterId)?.textbookPages?"词义":"本句",badges:studio.badges(w.id,true),context:contextText(occ,w.id),source,wordnet:window.WordNet.section(w.en,E),ipaData:window.DUAL_IPA,rate:window.Pronunciation.getPreferences().rate||1,voiceOptions:window.Pronunciation.voiceOptions(E),hasAudio:!!audioSource(w.id)||window.Pronunciation.allVoices().some(v=>v.packId),innerOnly,headerTools,translationTools});
}
function attachReader(){const sc=$('#reading-scroll'),p=state.progress[currentChapter.id],filter=$('[data-reader-filter]'),read=$('[data-read-page-words]');if(filter&&read)filter.after(read);if(p)requestAnimationFrame(()=>{sc.scrollTop=(sc.scrollHeight-sc.clientHeight)*(p.ratio||0);});sc.addEventListener('scroll',()=>{lastActive=Date.now();clearTimeout(scrollTimer);scrollTimer=setTimeout(saveScroll,250);},{passive:true});}
function saveScroll(){const sc=$('#reading-scroll');if(view!=='reader'||!sc||!currentChapter)return;const previous=state.progress[currentChapter.id]||{};const denominator=sc.scrollHeight-sc.clientHeight;const ratio=denominator>0?Math.min(1,Math.max(0,sc.scrollTop/denominator)):0;state.progress[currentChapter.id]={...previous,ratio,updated:Date.now()};const number=$('#read-percent'),bar=$('#read-bar');if(number)number.textContent=Math.round(ratio*100)+'%';if(bar)bar.style.width=(ratio*100)+'%';persist();}
function changeMode(mode){saveScroll();clearTimeout(challengePeekTimer);challengePeekToken=null;challengeCardExpanded=false;challengeCardLocked=false;state.settings.mode=mode;const sc=$('#reading-scroll'),ratio=state.progress[currentChapter.id]?.ratio||0;const art=$('#story-text');art.dataset.mode=mode;art.innerHTML=storyHTML(currentChapter);$$('[data-mode]').filter(el=>el.tagName==='BUTTON').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode);});refreshWordCard();requestAnimationFrame(()=>sc.scrollTop=ratio*(sc.scrollHeight-sc.clientHeight));persist();}
function revealChallengeGloss(token){clearTimeout(challengePeekTimer);challengePeekToken?.classList.remove('challenge-peek');challengePeekToken=token;token.style.setProperty('--challenge-shift-x','0px');token.classList.add('challenge-peek');requestAnimationFrame(()=>{const pop=token.querySelector('.challenge-popover'),sc=token.closest('.reading-scroll');if(!pop||!sc)return;const bounds=sc.getBoundingClientRect(),box=pop.getBoundingClientRect(),pad=8;token.style.setProperty('--challenge-max-width',Math.max(180,bounds.width-pad*2)+'px');let shift=0;if(box.left<bounds.left+pad)shift+=bounds.left+pad-box.left;if(box.right+shift>bounds.right-pad)shift-=box.right+shift-(bounds.right-pad);token.style.setProperty('--challenge-shift-x',shift+'px');});challengePeekTimer=setTimeout(()=>{token.classList.remove('challenge-peek');if(challengePeekToken===token)challengePeekToken=null;},5000);}
let wordRequest=0;
function selectWord(id,chapterId,paragraph,originalId=id){
 const request=++wordRequest,w=D.words[id];if(!w)return;
 const target=chapter(chapterId||currentChapter?.id||w.occurrences[0]?.chapterId).bookId;
 if(window.LazyBooks?.needs(target)){notify('正在读取词条所在的书…');window.LazyBooks.ensure(target).then(()=>{if(request===wordRequest)selectWord(id,chapterId,paragraph,originalId);}).catch(err=>notify(err.message));return;}

 const savedContext=state.saved[id],targetChapter=chapter(chapterId||currentChapter?.id);if(savedContext?.matchedGloss&&savedContext.chapterId===targetChapter.id&&savedContext.paragraph===paragraph&&targetChapter.chineseMechanicalVersion&&window.BilingualMechanical.context(targetChapter,paragraph)!==undefined){const prior=w.occurrences.find(o=>o.chapterId===targetChapter.id&&o.paragraph===paragraph);const recovered={chapterId:targetChapter.id,paragraph,gloss:savedContext.matchedGloss,source:'chinese-mechanical'};if(prior)Object.assign(prior,recovered);else w.occurrences.push(recovered);}
 const occ=w.occurrences.find(o=>o.chapterId===(chapterId||currentChapter?.id)&&(paragraph===undefined||o.paragraph===paragraph))||w.occurrences[0];
 if(view==='reader'&&state.settings.mode!=='challenge'&&innerWidth<=900&&document.body.classList.contains('word-open')&&selected?.id===id&&selected.chapterId===occ.chapterId&&selected.paragraph===occ.paragraph){closeWordSidebar();return;}
 selected={id,originalId,chapterId:occ.chapterId,paragraph:occ.paragraph};
 if(view==='reader'){
  const panel=$('#word-panel');panel.innerHTML=wordPanel();panel.parentElement.scrollTop=0;
  $$('.word-token.selected').forEach(x=>x.classList.remove('selected'));
  $$(`.word-token[data-word="${id}"][data-paragraph="${occ.paragraph}"]`).forEach(x=>x.classList.add('selected'));
  if(innerWidth<=900||(innerWidth<=1090&&state.settings.wordPosition==='right'))document.body.classList.add('word-open');
 }else{
  let panel=$('#lookup-sidebar');if(!panel){panel=document.createElement('aside');panel.id='lookup-sidebar';panel.className='lookup-sidebar';panel.setAttribute('aria-label','词语学习侧栏');(view==='vocab'?$('.vocab-layout'):document.body).append(panel);if(view==='vocab')$('.vocab-layout').classList.add('has-lookup');}
  panel.innerHTML=wordPanel();panel.scrollTop=0;
 }
 if(state.settings.autoSpeak)speak(id);
}
