document.addEventListener('submit',event=>{if(event.target.id==='spelling-form'){event.preventDefault();answerQuestion($('#spelling-answer').value);}});
let searchTimer;document.addEventListener('input',event=>{lastActive=Date.now();if(event.target.id==='translation-search'){const value=event.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const results=$('#translation-results');if(results)results.innerHTML=translationResultsHTML(value);},140);return;}if(event.target.id==='global-search'||event.target.id==='vocab-search'){const isGlobal=event.target.id==='global-search',value=event.target.value,position=event.target.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(isGlobal)search=value;else{vocabSearch=value;vocabPage=0;}render();const field=$(isGlobal?'#global-search':'#vocab-search');field?.focus();field?.setSelectionRange(position,position);},180);}});
document.addEventListener('change',event=>{const t=event.target;if(t.id==='reader-line-height'||t.id==='setting-line-height'){setLineHeight(t.value);}if(t.id==='import-file'){importState(t.files[0]);t.value='';}if(t.id==='setting-autospeak'){state.settings.autoSpeak=t.checked;persist();if(!t.checked)stopAudio();notify(t.checked?'点击词语时会自动朗读。':'已关闭自动朗读。');}if(t.id==='setting-mode'){state.settings.mode=t.value;persist();notify('阅读偏好已保存。');}if(t.id==='setting-font'){state.settings.fontSize=Number(t.value);persist();notify('字号已保存。');}if(t.id==='setting-goal'){state.settings.goal=Number(t.value);persist();notify('今日小目标已更新。');}});
document.addEventListener('keydown',event=>{lastActive=Date.now();if(event.key==='Escape'){if(dialogs.firstChild){const wasLearning=!!(session||reviewSession);closeDialog();if(wasLearning&&view!=='reader')render();}else closeWordSidebar();return;}if(event.key==='Tab'&&dialogs.firstChild){const items=[...dialogs.querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,[tabindex="0"]')];const first=items[0],last=items[items.length-1];if(!first){event.preventDefault();return;}if(event.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('modal'))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement.classList.contains('modal'))){event.preventDefault();first.focus();}}if(session&&!session.answered&&!/INPUT|TEXTAREA/.test(event.target.tagName)){const q=session.questions[session.index],index='abcd'.indexOf(event.key.toLowerCase());if(q?.type==='choice'&&index>=0&&index<q.choices.length){event.preventDefault();answerQuestion(q.choices[index]);}}});
document.addEventListener('pointerdown',()=>lastActive=Date.now(),{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden){saveScroll();persist();}lastTick=Date.now();});window.addEventListener('beforeunload',()=>{saveScroll();persist();stopAudio();});
setInterval(()=>{const now=Date.now(),elapsed=Math.min(15,(now-lastTick)/1000);lastTick=now;if(view==='reader'&&!document.hidden&&!dialogs.firstChild&&now-lastActive<120000){C.ensureDay(state,now).seconds+=Math.round(elapsed);persist();}},10000);
const match=location.hash.match(/^#(shelf|scenes|book|reader|lexicons|vocab|review|settings|studio|import)(?:\/([a-z0-9-]+))?$/);if(match){view=match[1];if(view==='lexicons')lexiconBrowser.setList(match[2]);if(view==='reader'&&D.chapters.some(c=>c.id===match[2]))state.lastChapter=match[2];if(view==='book'&&D.books.some(b=>b.id===match[2]))activeBookId=match[2];}if(view==='reader')activeBookId=chapter(state.lastChapter).bookId;if((view==='reader'||view==='book')&&(packages.deleted(activeBookId)||!visibleBooks().length))view='shelf';
